Record
mixin_of (T0 : Type) (b : Order.POrder.class_of T0)
(T : porderType tt := Order.POrder.Pack tt b) : Type := Mixin
  { meet : T -> T -> T;
    join : T -> T -> T;
    _ : commutative meet;
    _ : commutative join;
    _ : associative meet;
    _ : associative join;
    _ : forall y x : T, meet x (join x y) = x;
    _ : forall y x : T, join x (meet x y) = x;
    _ : forall x y : T, (x <= y)%O = eqtype.eq_op (meet x y) x }.

