Record
mixin_of (T0 : Type) (b : eqtype.Equality.mixin_of T0)
(T : eqtype.Equality.type := eqtype.Equality.Pack b) : Type := Mixin
  { le : rel (eqtype.Equality.sort T);
    lt : rel (eqtype.Equality.sort T);
    _ : forall x y : eqtype.Equality.sort T,
        lt x y = ~~ eqtype.eq_op y x && le x y;
    _ : reflexive (T:=eqtype.Equality.sort T) le;
    _ : antisymmetric (T:=eqtype.Equality.sort T) le;
    _ : transitive (T:=eqtype.Equality.sort T) le }.

