cd /tmp && python3 - <<'PY'
# Scan lines 850-1860 for bullet tokens at line starts and stack nesting
lines=open('dia2.v').read().splitlines()
stack=[]
issues=[]
for idx,l in enumerate(lines[850:1862], start=851):
    st=l.lstrip()
    if st[:2] in ('- ','+ ','* ') and l.startswith('  '):
        tok=st[0]
        # determine
        if not stack:
            if tok!='-': issues.append((idx,'first bullet not -',l[:60]))
            stack=[tok]
        else:
            if tok==stack[-1]:
                # sibling at current level
                pass
            else:
                # new bullet: must be deeper and different
                order='-+*'
                if order.index(tok) > order.index(stack[-1]) and tok not in stack:
                    stack.append(tok)
                else:
                    issues.append((idx,'bad transition stack='+''.join(stack),l[:80]))
print('issues',len(issues))
for x in issues[:40]: print(x)
print('final stack',''.join(stack))
PY

cd /tmp && python3 - <<'PY'
lines=open('dia2.v').read().splitlines()
# Determine region: from line starting '  - (* Var *) move=> P1 psi xv psi0 u i b c H2.' (Par_diamond_mut Var) to final Qed
start=None
for i,l in enumerate(lines):
    if l.startswith('  - (* Var *) move=> P1 psi xv psi0 u i b c H2.'):
        # There are earlier Var cases; choose the one after 'apply (@Par_diam_comb'
        if any('Par_diam_comb' in x for x in lines[max(0,i-20):i]):
            start=i; break
if start is None:
    # find line with apply Par_diam_comb then next '- Var'
    for i,l in enumerate(lines):
        if 'apply (@Par_diam_comb' in l:
            j=i+1
            while j<len(lines) and not lines[j].startswith('  - '): j+=1
            start=j; break
print('start',start+1, lines[start])
# find end Qed index after start (the final Qed)
end=None
for i in range(start,len(lines)):
    if lines[i].strip()=='Qed.':
        end=i; break
print('end',end+1,lines[end])
# transform region: each line starting '  - (' -> '  { (' ; before each such line except first insert '  }'
out=lines[:start]
first=True
for i in range(start,end):
    l=lines[i]
    if l.startswith('  - ('):
        if not first:
            out.append('  }')
        out.append('  { ('+l[len('  - ('):])
        first=False
    else:
        out.append(l)
out.append('  }')
out.extend(lines[end:])
open('test16.v','w').write('\n'.join(out)+'\n')
PY
